const B = (command) => ({ tool: "Bash", input: { command } });
const W = (file_path, content = "x") => ({ tool: "Write", input: { file_path, content } });
const E = (file_path, new_string = "x") => ({
  tool: "Edit",
  input: { file_path, old_string: "a", new_string },
});
const R = (file_path) => ({ tool: "Read", input: { file_path } });
const G = (path, glob) => ({ tool: "Grep", input: { pattern: "x", path, glob } });
const GL = (pattern, path) => ({ tool: "Glob", input: { pattern, path } });
const NB = (notebook_path, new_source = "x") => ({
  tool: "NotebookEdit",
  input: { notebook_path, new_source },
});
const MCP = (tool) => ({ tool, input: {} });

